import pathlib,json,re
root=pathlib.Path(__file__).resolve().parents[1]
medical=['Dhaka Medical College','Sir Salimullah Medical College','Mymensingh Medical College','Chittagong Medical College','Rajshahi Medical College','Sher-E-Bangla Medical College','Shaheed Suhrawardy Medical College','Chandpur Medical College','Dhaka National Medical College','Bangladesh Medical College','Popular Medical College','Ibrahim Medical College','Enam Medical College',"Kumudini Women's Medical College",'Green Life Medical College','United Medical College']
dental=['Dhaka Dental College','Pioneer Dental College','City Dental College','University Dental College','Chittagong International Dental College']
textile=['Tangail Textile Engineering College, Kalihati, Tangail','Gopalgonj Textile Engineering College, Gopalgonj','Jhenaidah Textile Engineering College, Jhenaidah','Rangpur Textile Engineering College, Pirgonj, Rangpur','Begumgonj Textile Engineering College','Pabna Textile Engineering College','Barisal Textile Engineering College, Barisal','Textile Engineering College Chittagong','Narsingdi Textile Engineering College, Narsingdi','Jamalpur Textile Engineering College, Melandaho, Jamalpur']
result=[]
for kind,names,source,url in [('medical_college',medical,'bmdc','https://www.bmdc.org.bd/about-college-n'),('dental_college',dental,'bmdc','https://www.bmdc.org.bd/about-college-n'),('textile_college',textile,'butex','https://newsite.butex.edu.bd/all-affiliate-institutes'),('textile_institute',['National Institute of Textile Engineering and Research'],'niter','https://www.niter.edu.bd/admission-info/')]:
 for i,name in enumerate(names):
  slug=re.sub('[^a-z0-9]+','-',name.lower()).strip('-')
  result.append(dict(id=source+'-'+str(i+1) if source!='bmdc' else kind+'-'+str(i+1),slug=slug,name_en=name,name_bn=None,kind=kind,category=None,ownership='unknown',directory_listed=False,source_id=source,source_url=url,snapshot_date='2026-11-06',provenance='Specialist identity example from supplied blueprint, not an exhaustive inventory. Current recognition and admissions require individual review.',notice_flag=False,regulatory_status='not_verified',admission_permission='not_verified',website_raw=None,website_url=None,website_verified=False,division=None,district=None,founding_year=None,aliases=[],tags=['textile'] if 'textile' in kind else [],parent_id='ugc-public-033' if kind=='textile_college' else 'ugc-public-001' if source=='niter' else None,affiliation_status='source_snapshot' if 'textile' in kind else 'not_verified'))
(root/'data/seeds/specialists.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n')
print(len(result),'specialist identity examples')
